        return None

    if not path.startswith('/'):
        path = cwd + '/' + path if cwd != '/' else '/' + path

    components = path.split('/')
    current = []
    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        if comp == '' or comp == '.':
            i += 1
            continue

        if comp == '..':
            if current:
                current.pop()
            i += 1
            continue

        current.append(comp)
        current_path = '/' + '/'.join(current) if current else '/'

        if current_path in links:
            if link_count >= 8:
                return None

            link_count += 1
            target = links[current_path]

            if target.startswith('/'):
                current = []
                target_components = target.split('/')
            else:
                current.pop()
                parent_path = '/' + '/'.join(current) if current else '/'
                target_components = (parent_path + '/' + target).split('/')

            components = target_components + components[i + 1:]
            i = 0
        else:
            i += 1

    result = '/' + '/'.join(current) if current else '/'
    return result

